To calculate the probability of interest, we begin by analyzing a simplified experiment. Suppose there are $b$ range items $r_1, \dots, r_b$ each appearing greater than $T$ times in $x$. We compute the probability that \emph{none} of the items $r_1, \dots, r_b$ appear in the sample $x_\Scal$. If $T \ge N - S$, then this probability is zero. Otherwise, by direct calculation, we have for each $i = 1, \dots, b$: \[\Pr_{\Scal}[r_i 
otin x_\Scal | r_1 
otin x_\Scal, \dots, r_{i-1} 
otin x_\Scal] \le \prod_{j = 0}^{S-1} \left(1 -  rac{T}{N-j} ight) \le \left( 1 -  rac{T}{N}ight)^S \le \exp \left(- rac{ST}{N} ight).\] Hence the probability that none of $r_1, \dots, r_b$ appear is \[\Pr_{\Scal}[r_1 
otin x_\Scal \land \dots \land r_b 
otin x_\Scal] = \prod_{i = 1}^b \Pr_{\Scal}[r_i 
otin x_\Scal | r_1 
otin x_\Scal, \dots, r_{i-1} 
otin x_\Scal] \le \exp \left(- rac{bST}{N} ight).\] Now fix an arbitrary $x$, and let $r_1, \dots, r_{k}$ be the range items appearing greater than $T$ times in $x$. Observe that $k \le N/T$. We estimate the probability of interest by taking a union bound over all subsets of $r_1, \dots, r_k$ of size $b$:  egin{align*} \Pr_{\Scal}[b_{\Rcal(x_\Scal)}(x) \ge b] &\le \sum_{Y \subseteq [k] : |Y| = b} \Pr_{\Scal}[r_{i_j} 
otin x_\Scal \quad  orall j \in Y] \ & \le  inom{k}{b} \exp \left(- rac{bST}{N}ight) \ &\le \exp \left( - rac{bST}{N} + b \log Night). \end{align*}

By renormalizing, it suffices to construction a function $\omega : [T]_0 	o \R$ such that  egin{align} &\omega(0) - \sum_{t = 1}^T \omega(t) \ge (1 - \delta)\|\omega\|_1 \ & 	ext{For all univariate polynomials } q \colon \R 	o \R	ext{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \ & |\omega(t)| \le  rac{170 \exp(-c_2 t \sqrt{\delta} /\sqrt{T})\|\omega\|_1}{\delta \cdot t^2} \qquad  orall t = 1, \dots, T.\end{align} Let $c = \lceil 8 / \delta ceil$ below. We will freely use the fact that since $\delta \le 1/2$, we have $c \le c^2 / (c-1) \le 10 /\delta$. Let $m = \lfloor \sqrt{T/2c} floor$ and define the set \[S = \{1, c\} \cup \{2ci^2 : 0 \le i \le m\}.\] Note that $|S| \ge c_1 \sqrt{\delta T}$ for some absolute constant $c_1 > 0$. Define the function \[\omega(t) =  rac{(-1)^{t+(T-m)}}{T!}  inom{T}{t} \prod_{r \in [T]_0 \setminus S} (t - r).\] Property~\eqref{eqn:or-sym-phd-ref} follows from the following well-known combinatorial identity.  egin{fact}[e.g., \cite{concrete} Equation (5.23) or \cite{osnewbounds}] Let $T \in \N$, and let $p$ be a polynomial of degree less than $T$. Then \[\sum_{t = 0}^T (-1)^t  inom{T}{t} p(t) = 0.\] \end{fact} Expanding out the binomial coefficient in the definition of $\omega$ reveals that \[|\omega(t)| =  egin{cases} \prod\limits_{r \in S \setminus \{t\}}  rac{1}{|t - r|} & 	ext{ for } t \in S, \ 0 & 	ext{ otherwise.} \end{cases}\] We now use this characterization to establish the improved tail decay property \eqref{eqn:or-sym-decay-ref}. This clearly holds for $t = 1$ with $c_2 = 1/10$, since $|\omega(1)| \le \|\omega\|_1$ and \[ rac{170}{\delta} \exp(-c_2\sqrt{\delta} / \sqrt{T}) \ge 340 \cdot e^{-\sqrt{2} / 10} > 1.\] For $t = c$, we have  egin{align}  rac{|\omega(c)|}{\omega(0)} &=  rac{c\prod_{i = 1}^m (2ci^2)}{c(c-1)\prod_{i = 1}^m (2ci^2 - c)} 
onumber \ &=  rac{1}{c-1}\left(\prod_{i = 1}^m  rac{i^2 - 1/2}{i^2}ight)^{-1} 
onumber \ &\le  rac{1}{c-1} \left(1 - \sum_{i=1}^m  rac{1}{2i^2}ight)^{-1} 
onumber \ &\le  rac{1}{c-1} \left(1 -  rac{\pi^2}{12}ight)^{-1} \le  rac{6}{c - 1} \end{align} where the first inequality follows from the fact that $\prod_{i = 1}^m (1 - a_i) \ge 1 - \sum_{i = 1}^m a_i$ for $a_i \in (0, 1)$. Now note that  egin{align*}  rac{|\omega(c)|}{\|\omega\|_1} &\le  rac{|\omega(c)|}{\omega(0)} \ &\le  rac{6}{c - 1} \ &\le  rac{60}{\delta \cdot c^2} & 	ext{ since } 10/\delta \ge c^2 / (c-1) \ & \le  rac{170}{\delta \cdot c^2} \cdot e^{-c\sqrt{\delta}/10\sqrt{T}}, \end{align*} since $\delta \ge 1/T$ and hence $e^{-c\sqrt{\delta}/10\sqrt{T}} \ge e^{-1}$. Thus~\eqref{eqn:or-sym-decay-ref} holds for $t = c$, recalling that $c_2 = 1/10$. For $t = 2cj^2$ with $j \ge 1$, we get  egin{align*}  rac{|\omega(t)|}{\omega(0)} &=  rac{c\prod_{i = 1}^m (2ci^2)}{(2cj^2 - 1)(2cj^2-c)\prod_{i \in [m]_0 \setminus \{j\}} |2ci^2 - 2cj^2|} \ &=  rac{c(m!)^2}{(4c^2j^4 - (2c^2 + 2c)j^2 + c)\prod_{i \in [m]_0 \setminus \{j\}} (i+j)|i-j|} \ &=  rac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \cdot  rac{(m!)^2}{(m+j)!(m-j)!}. \end{align*} For $j \ge 1$, the first factor is bounded by \[ rac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \le  rac{3c}{(2cj^2)^2},\] using the fact that $c \ge 2$. We control the second factor by  egin{align*}  rac{(m!)^2}{(m+j)!(m-j)!} &=  rac{m}{m+j} \cdot  rac{m-1}{m+j-1} \cdot \ldots \cdot  rac{m-j+1}{m+1} \ &\le \left( rac{m}{m+j} ight)^j \ &\le \left(1 -  rac{j}{2m} ight)^j \ &\le e^{-j^2/2m}, \end{align*} where the last inequality uses the fact that $1 - x \le e^{-x}$ for all $x$. Since \[ rac{|\omega(t)|}{\|\omega\|_1} \le  rac{|\omega(2cj^2)|}{\omega(0)} \le  rac{3c}{(2cj^2)^2} \cdot e^{-2cj^2/(4cm)} \le  rac{170}{\delta \cdot t^2} \cdot e^{-t \sqrt{\delta} / 10 \sqrt{T}},\] this establishes~\eqref{eqn:or-sym-decay-ref}. What remains is to perform the correlation calculation to establish~\eqref{eqn:or-sym-corr-ref}. For $t = 1$, we observe \[ rac{|\omega(1)|}{\omega(0)} =  rac{c\prod_{i = 1}^m (2ci^2)}{(c-1)\prod_{i = 1}^m (2ci^2 - 1)} \ge \prod_{i=1}^m  rac{i^2}{i^2 - 1/(2c)} \ge 1.\] Next, we observe that the total contribution of $t > c$ to $\|\omega\|_1/\omega(0)$ is at most  egin{equation} \sum_{t > c}  rac{|\omega(t)|}{\omega(0)} \le \sum_{j=1}^{m}  rac{3c}{(2cj^2)^2} < \sum_{j=1}^\infty  rac{3}{4cj^4} =  rac{\pi^4}{120 c}. \end{equation} Next, we calculate  egin{align} \omega(0) - \sum_{t = 1}^T \omega(t) &\ge \omega(0) - \omega(1) - \left( \sum_{t = c}^T |\omega(t)|ight) 
onumber \ &\ge \omega(0) - \omega(1) - \left( \omega(c) + \omega(0) \cdot  rac{\pi^4}{120c}ight) & 	ext{by } \eqref{eqn:omega-tail} 
onumber \ &\ge - \omega(1) + \omega(0) \left(1 -  rac{6}{c-1} -  rac{\pi^4}{120c}ight) & 	ext{by } \eqref{eqn:omega-2} 
onumber \ &\ge - \omega(1) + (1 - \delta)\omega(0) & 	ext{by our choice of } c \ge 8/\delta. \end{align} On the other hand,  egin{align} \|\omega\|_1 &\le \omega(0) - \omega(1) + \omega(2) + \omega(0) \cdot  rac{\pi^4}{120c} & 	ext{by } \eqref{eqn:omega-tail} 
onumber \ &\le -\omega(1) + \omega(0) \left(1 +  rac{6}{c - 1} +  rac{\pi^4}{120c} ight) &	ext{by } \eqref{eqn:omega-2}
onumber \ &\le -\omega(1) + (1 + \delta)\omega(0) & 	ext{since } c \ge 8/\delta. \end{align} Combining~\eqref{eqn:fudgethis} and~\eqref{eqn:fudgethat}, and using the fact that $-\omega(1) \ge \omega(0)$ shows that \[ rac{\omega(0) - \sum_{t = 1}^k \omega(t)}{\|\omega\|_1} \ge  rac{-\omega(1) + (1-\delta) \omega(0)}{-\omega(1) + (1+\delta) \omega(0)} \ge  rac{2-\delta}{2 + \delta} \ge 1 - \delta.\] This establishes~\eqref{eqn:or-sym-corr-ref}, completing the proof.

For $t = c$, we have  egin{align}  rac{|\omega(c)|}{\omega(0)} &=  rac{c\prod_{i = 1}^m (2ci^2)}{c(c-1)\prod_{i = 1}^m (2ci^2 - c)} 
onumber \ &=  rac{1}{c-1}\left(\prod_{i = 1}^m  rac{i^2 - 1/2}{i^2}ight)^{-1} 
onumber \ &\le  rac{1}{c-1} \left(1 - \sum_{i=1}^m  rac{1}{2i^2}ight)^{-1} 
onumber \ &\le  rac{1}{c-1} \left(1 -  rac{\pi^2}{12}ight)^{-1} \le  rac{6}{c - 1} \end{align} where the first inequality follows from the fact that $\prod_{i = 1}^m (1 - a_i) \ge 1 - \sum_{i = 1}^m a_i$ for $a_i \in (0, 1)$. Now note that  egin{align*}  rac{|\omega(c)|}{\|\omega\|_1} &\le  rac{|\omega(c)|}{\omega(0)} \ &\le  rac{6}{c - 1} \ &\le  rac{60}{\delta \cdot c^2} & 	ext{ since } 10/\delta \ge c^2 / (c-1) \ & \le  rac{170}{\delta \cdot c^2} \cdot e^{-c\sqrt{\delta}/10\sqrt{T}}, \end{align*} since $\delta \ge 1/T$ and hence $e^{-c\sqrt{\delta}/10\sqrt{T}} \ge e^{-1}$. Thus~\eqref{eqn:or-sym-decay-ref} holds for $t = c$, recalling that $c_2 = 1/10$.

What remains is to perform the correlation calculation to establish~\eqref{eqn:or-sym-corr-ref}. For $t = 1$, we observe \[ rac{|\omega(1)|}{\omega(0)} =  rac{c\prod_{i = 1}^m (2ci^2)}{(c-1)\prod_{i = 1}^m (2ci^2 - 1)} \ge \prod_{i=1}^m  rac{i^2}{i^2 - 1/(2c)} \ge 1.\] Next, we observe that the total contribution of $t > c$ to $\|\omega\|_1/\omega(0)$ is at most  egin{equation} \sum_{t > c}  rac{|\omega(t)|}{\omega(0)} \le \sum_{j=1}^{m}  rac{3c}{(2cj^2)^2} < \sum_{j=1}^\infty  rac{3}{4cj^4} =  rac{\pi^4}{120 c}. \end{equation} Next, we calculate  egin{align} \omega(0) - \sum_{t = 1}^T \omega(t) &\ge \omega(0) - \omega(1) - \left( \sum_{t = c}^T |\omega(t)|ight) 
onumber \ &\ge \omega(0) - \omega(1) - \left( \omega(c) + \omega(0) \cdot  rac{\pi^4}{120c}ight) & 	ext{by } \eqref{eqn:omega-tail} 
onumber \ &\ge - \omega(1) + \omega(0) \left(1 -  rac{6}{c-1} -  rac{\pi^4}{120c}ight) & 	ext{by } \eqref{eqn:omega-2} 
onumber \ &\ge - \omega(1) + (1 - \delta)\omega(0) & 	ext{by our choice of } c \ge 8/\delta. \end{align} On the other hand,  egin{align} \|\omega\|_1 &\le \omega(0) - \omega(1) + \omega(2) + \omega(0) \cdot  rac{\pi^4}{120c} & 	ext{by } \eqref{eqn:omega-tail} 
onumber \ &\le -\omega(1) + \omega(0) \left(1 +  rac{6}{c - 1} +  rac{\pi^4}{120c} ight) &	ext{by } \eqref{eqn:omega-2}
onumber \ &\le -\omega(1) + (1 + \delta)\omega(0) & 	ext{since } c \ge 8/\delta. \end{align} Combining~\eqref{eqn:fudgethis} and~\eqref{eqn:fudgethat}, and using the fact that $-\omega(1) \ge \omega(0)$ shows that \[ rac{\omega(0) - \sum_{t = 1}^k \omega(t)}{\|\omega\|_1} \ge  rac{-\omega(1) + (1-\delta) \omega(0)}{-\omega(1) + (1+\delta) \omega(0)} \ge  rac{2-\delta}{2 + \delta} \ge 1 - \delta.\] This establishes~\eqref{eqn:or-sym-corr-ref}, completing the proof.
